  /**
   * Helper method to check if a coordinate is already filled
   * @LLM */
  private boolean isFilled(Coordinate coord) {
    return filledTiles.contains(coord);
  }

  /**
   * Helper method to check if a neighbor cell is valid for connection in direction d
   * @LLM */
  private boolean isValidConnection(Cell neighborCell, Direction direction) {
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    if (neighborCell instanceof FillableCell) {
      Pipe pipe = ((FillableCell) neighborCell).getPipe();
      if (pipe == null) {
        return false;
      }
      // Check if the pipe has an opening in the opposite direction
      Direction oppositeDirection = helper.getOpposite(direction);
      return pipe.getConnections().contains(oppositeDirection);
    } else if (neighborCell instanceof TerminationCell) {
      // TerminationCell connects if its direction matches the incoming direction
      // Or if it's a sink/source that accepts water
      Direction neighborDir = ((TerminationCell) neighborCell).getPointingTo();
      if (neighborDir == null) {
        return false;
      }
      return neighborDir == helper.getOpposite(direction);
    }
    return false;
  }

